const categories = {'all':'All news','industrial-robots':'Industrial robots','humanoids':'Humanoids','ai-automation':'AI & automation','research':'Research','drones':'Drones','industry-news':'Industry news'};
const articles = window.ROBOT_NEWS_ARTICLES;
const $=s=>document.querySelector(s), params=new URLSearchParams(location.search);
let category=categories[params.get('category')]?params.get('category'):'industrial-robots', page=1;
const perPage=6, esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
$('#source').innerHTML += [...new Set(articles.map(a=>a.source))].sort().map(s=>`<option>${esc(s)}</option>`).join('');
function setCategory(c){category=c;page=1;const u=new URL(location);u.searchParams.set('category',c);history.replaceState(null,'',u);render()}
function filtered(){const q=$('#search').value.trim().toLocaleLowerCase();return articles.filter(a=>(category==='all'||a.category===category)&&(!$('#source').value||a.source===$('#source').value)&&(`${a.title} ${a.summary} ${a.source}`.toLocaleLowerCase().includes(q))).sort((a,b)=>$('#sort').value==='old'?a.date.localeCompare(b.date):b.date.localeCompare(a.date))}
function render(){
$('#categories').innerHTML=Object.entries(categories).map(([key,label])=>`<button data-category="${key}" class="${category===key?'active':''}" aria-pressed="${category===key}">${label}</button>`).join('');
const results=filtered(), total=Math.ceil(results.length/perPage); page=Math.max(1,Math.min(page,total||1));
$('#section-title').textContent=categories[category];$('#count').textContent=`${results.length} articles`;
$('#grid').innerHTML=results.length?results.slice((page-1)*perPage,page*perPage).map(a=>`<article class="card"><button class="image-button" data-open="${a.id}" aria-label="Read ${esc(a.title)}">${a.image?`<img src="${esc(a.image)}" alt="${esc(a.title)}" loading="lazy">`:`<span class="image-fallback">${esc(a.source)}</span>`}</button><div class="card-body"><div class="tag-row"><span class="tag">${categories[a.category]}</span><span class="fresh">English summary</span></div><h3><button class="headline" data-open="${a.id}">${esc(a.title)}</button></h3><p class="summary">${esc(a.summary)}</p><div class="metadata"><a class="source-link" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.source)}</a><time datetime="${a.date}">${date(a.date)}</time></div><div class="card-bottom"><button class="read-more" data-open="${a.id}">Read full story <span aria-hidden="true">↗</span></button><button class="copy" data-copy="${a.id}" aria-label="Copy article link: ${esc(a.title)}">Copy link ⧉</button></div></div></article>`).join(''):`<div class="empty"><h3>No matching stories</h3><p>Try another search term, source or category.</p><button id="reset">Clear filters</button></div>`;
$('#pagination').innerHTML=total>1?`<button data-page="${page-1}" ${page===1?'disabled':''}>← Previous</button>${Array.from({length:total},(_,i)=>`<button data-page="${i+1}" class="${page===i+1?'active':''}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-page="${page+1}" ${page===total?'disabled':''}>Next →</button>`:'';
document.querySelectorAll('.image-button img').forEach(img=>img.addEventListener('error',()=>{const a=articles.find(a=>a.id===img.parentElement.dataset.open);img.parentElement.innerHTML=`<span class="image-fallback">${esc(a.source)}</span>`},{once:true}));
}
function openArticle(id){if(articles.some(a=>a.id===id))location.assign('/en/articles/'+encodeURIComponent(id)+'.html')}
function info(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category)setCategory(b.dataset.category);if(b.dataset.open)openArticle(b.dataset.open);if(b.dataset.page){page=Number(b.dataset.page);render();$('#news').scrollIntoView({behavior:'smooth',block:'start'})}if(b.id==='reset'){$('#search').value='';$('#source').value='';setCategory('all')}if(b.dataset.copy){const u=new URL('/en/articles/'+encodeURIComponent(b.dataset.copy)+'.html',location.origin);try{await navigator.clipboard.writeText(u.href);$('#toast').textContent='Article link copied';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2400)}catch{info(`<h2>Article link</h2><p>Select and copy the link below</p><input aria-label="Article link" readonly value="${esc(u.href)}">`)}}});
['search','source','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=1;render()}));
$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#sources-button').onclick=()=>info(`<h2>Our sources</h2><p>This collection features reporting from ${new Set(articles.map(a=>a.source)).size} sources. Every story links back to the original article.</p><ul>${[...new Set(articles.map(a=>a.source))].map(s=>`<li><a href="${new URL(articles.find(a=>a.source===s).url).origin}" target="_blank" rel="noopener noreferrer">${esc(s)} ↗</a></li>`).join('')}</ul>`);
$('#about-button').onclick=()=>info('<h2>Robotics, clearly explained</h2><p>Robot News brings together robotics and automation stories from around the world, with accessible summaries to help you follow the technology.</p><p>We select and check stories from multiple sources, with detailed summaries, images, videos and links to the originals.</p><p>The layout is inspired by Robot News. This is an independent website and is not affiliated with the original Robot News site.</p>');
try{if(localStorage.getItem('robot-theme')==='dark')document.body.classList.add('dark')}catch{}
$('#theme').onclick=()=>{const dark=document.body.classList.toggle('dark');try{localStorage.setItem('robot-theme',dark?'dark':'light')}catch{}$('#theme').textContent=dark?'☀':'☾'};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();$('#search').focus()}});
render();if(params.has('article'))openArticle(params.get('article'));

const edition=document.querySelector('.edition b');if(edition&&window.ROBOT_NEWS_UPDATED_AT)edition.textContent=new Date(window.ROBOT_NEWS_UPDATED_AT).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
